const input = $input.first();
const json = (input && input.json) || {};

// Nhận diện nguồn gọi (Webhook Fast-Path vs Mattermost Router)
let triggerSource = 'mattermost';
let reqIssueKey = '';

try {
  const trig = $('Webhook Trigger (jira-prep)').first();
  if (trig && trig.json) {
    triggerSource = 'webhook';
    reqIssueKey = trig.json.body?.issueKey || trig.json.issueKey || '';
  }
} catch (e) {
  // Không gọi từ Webhook
}

if (!reqIssueKey) {
  try {
    const trig = $('Execute Workflow Trigger').first();
    if (trig && trig.json) {
      triggerSource = 'mattermost';
      reqIssueKey = trig.json.body?.params?.issueKey || trig.json.body?.issueKey || trig.json.params?.issueKey || trig.json.issueKey || '';
    }
  } catch (e) {
    // Không gọi từ Execute Workflow Trigger
  }
}

// ── Kiểm tra và xử lý lỗi từ Jira REST API (404, 401, timeout...) ───────────
if (json.error || json.errorMessages || (json.message && !json.fields)) {
  const errMsg = (json.errorMessages && json.errorMessages.join(', ')) ||
                 (json.error && (json.error.message || json.error.description)) ||
                 json.message || 'Không thể kết nối đến Jira REST API';

  const formattedError = `🚨 **[Lỗi Tra Cứu Jira]** Không thể lấy thông tin issue [${reqIssueKey || 'chưa nhập'}]:\n> ${errMsg}\n\n*Gợi ý: Hãy kiểm tra mã issueKey (VD: G3PTP-17396) và quyền hạn tài khoản trong .env.*`;

  return [{
    json: {
      isError: true,
      error: errMsg,
      issueKey: reqIssueKey,
      reportText: formattedError,
      _triggerSource: triggerSource
    }
  }];
}

// ── Xử lý dữ liệu khi thành công ─────────────────────────────────────────────
const fields = json.fields || {};
let cleanDesc = '';
if (fields.description && fields.description.content) {
  cleanDesc = JSON.stringify(fields.description.content);
} else if (typeof fields.description === 'string') {
  cleanDesc = fields.description;
}

const attachments = fields.attachment ? fields.attachment.map(a => ({ filename: a.filename, size: a.size, content: a.content })) : [];
const issueLinks = fields.issuelinks ? fields.issuelinks.map(l => l.outwardIssue ? l.outwardIssue.key : (l.inwardIssue ? l.inwardIssue.key : null)).filter(Boolean) : [];
const issueKey = json.key || reqIssueKey;

const reportText = `### 📋 Jira Issue: [${issueKey}] ${fields.summary || ''}\n- **Trạng thái:** ${fields.status ? fields.status.name : 'Unknown'}\n- **Người xử lý:** ${fields.assignee ? fields.assignee.displayName : 'Chưa phân bổ'}\n- **Người báo cáo:** ${fields.reporter ? fields.reporter.displayName : 'Unknown'}\n- **Liên kết:** ${issueLinks.join(', ') || 'Không có'}\n- **Tóm tắt mô tả:**\n> ${cleanDesc.substring(0, 500)}`;

return [{
  json: {
    isError: false,
    issueKey: issueKey,
    summary: fields.summary || '',
    status: fields.status ? fields.status.name : 'Unknown',
    assignee: fields.assignee ? fields.assignee.displayName : 'Unassigned',
    reporter: fields.reporter ? fields.reporter.displayName : 'Unknown',
    labels: fields.labels || [],
    attachments: attachments,
    issueLinks: issueLinks,
    descriptionSnippet: cleanDesc.substring(0, 1500),
    reportText: reportText,
    _triggerSource: triggerSource
  }
}];
